pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the residual left in the bin after placement
    let mut score = post_residual as f64;

    // Prefer placements that leave a residual close to or below the mean residual
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Penalize bins that cannot accommodate the next item
    if next_item_size > post_residual {
        score += (next_item_size as f64 - post_residual as f64) * 1.2;
    }

    // If this is the only bin that can fit the item, discourage opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score += 15.0;
    }

    // When the stream is near its end, favor opening a new bin if it fits the item
    let fraction_done = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity && fraction_done > 0.8 {
        score -= 10.0;
    }

    // Slight bias toward using existing bins when many are open
    score += (open_bins_count as f64) * 0.1;

    // Reward large items that take up a significant portion of the bin
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Penalize if the remaining space after placement is too small for the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    score
}

