    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64 / bin_capacity as f64;
    let fit_factor = fitting_bins_count as f64 / (open_bins_count as f64 + 1.0);
    let mean_norm = mean_residual / bin_capacity as f64;

    let mut score = r;

    // Penalize high residuals increasingly as the stream progresses
    score += r * r * progress;

    // Penalize bins when few fitting bins exist
    score += (1.0 - fit_factor) * r * r * progress;

    // Penalize residuals above the mean residual
    if r > mean_norm {
        score += (r - mean_norm) * (1.0 - progress);
    }

    // Small reward if the residual can accommodate the next item
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / bin_capacity as f64;
        if r >= next_norm {
            score -= (1.0 - r) * (1.0 - progress) * ((open_bins_count as f64) + 1.0);
        }
    }

    score
}

pub fn score_bin(
