    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base waste penalty
    let mut score = post_residual as f64 * 0.90;

    // Residual deviation from the mean
    let delta_mean = (post_residual as f64 - mean_residual).abs();
    score += delta_mean * 0.25;

    // If the next item does not fit, penalise more when the residual is already small
    if next_item_size > post_residual {
        let gap = (next_item_size as f64 - post_residual as f64).powi(2);
        let extra = (mean_residual - post_residual as f64).max(0.0) / mean_residual;
        score += gap * 0.60 * (1.0 + extra);
    }

    // When this is the only fitting bin, discourage opening a new bin unless the residual is very large
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual as f64 <= mean_residual * 1.40 {
            score += 10.0;
        }
    }

    // Handle a brand‑new empty bin
    if bin_residual == bin_capacity {
        // Prefer a fresh bin for large items
        let ratio = item_size as f64 / bin_capacity as f64;
        score -= ratio * 30.0;
        // But penalise when many bins are already open
        score += (open_bins_count as f64).sqrt() * 0.30;
    }

    // Late‑stream bias: favour a new bin if the stream is almost finished
    let fraction_done = step_index as f64 / total_items as f64;
    if fraction_done > 0.95 {
        if bin_residual != bin_capacity {
            score += 10.0;
        } else {
            score -= 10.0;
        }
    }

    // Penalise an excessive number of open bins
    let max_allowed = (total_items as f64 * 0.04).max(4.0);
    if open_bins_count as f64 > max_allowed {
        score += 0.10 * (open_bins_count as f64 - max_allowed);
    }

    // Reward packing a large fraction of the bin while keeping residual small
    let packed_fraction = item_size as f64 / bin_capacity as f64;
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (packed_fraction * (1.0 - residual_ratio)).powi(2) * 20.0;

    // If the next item is tiny and we leave a lot of space, penalise
    if next_item_size < 8 && post_residual > 25 {
        score += 3.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
