    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: residual left after placement (scaled down)
    let mut score = post_residual as f64 * 0.75;

    // Penalize deviation from the mean residual
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.30;

    // Fill‑ratio penalty (squared to discourage near‑full bins)
    let used_ratio = 1.0 - post_residual as f64 / bin_capacity as f64;
    score += used_ratio.powi(2) * 3.5;

    // New‑bin handling: lower baseline cost, but still penalize many bins
    if bin_residual == bin_capacity {
        score += 6.5;
        score += (open_bins_count as f64) * 0.12;
    }

    // Only one fitting bin: discourage taking the sole slot
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score += 10.0;
    }

    // End‑of‑stream bias: prefer new bins near the end
    let fraction_done = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity && fraction_done > 0.90 {
        score -= 10.0;
    }

    // Reward large items that take a large share of a bin
    let item_ratio = item_size as f64 / bin_capacity as f64;
    if item_ratio > 0.70 {
        score -= 12.0;
    }

    // Lookahead for the next item
    if next_item_size > 0 {
        // Immediate gap if next item won't fit
        if next_item_size > post_residual {
            let gap = next_item_size as f64 - post_residual as f64;
            score += gap * 1.20;
            // Extra penalty if the next item is itself large
            if next_item_size > bin_capacity / 2 {
                score += 2.0;
            }
        }
        // General penalty for insufficient space
        if post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Dead‑space penalty: discourage bins with large leftover
    let dead_space_ratio = post_residual as f64 / bin_capacity as f64;
    if dead_space_ratio > 0.40 {
        score += dead_space_ratio * 5.0;
    }

    // Small residual penalty: bins that leave a tiny unusable hole
    if bin_residual > 0 && bin_residual < 10 {
        score += 5.0;
    }

    // Extra cost when many bins are open
    if open_bins_count > 5 {
        score += 0.5 * (open_bins_count as f64 - 5.0);
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Basic normalised residuals
    let r = post_residual as f64 / bin_capacity as f64;
    let mean_norm = mean_residual / bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;

    // Fit factor: fraction of open bins that can still accommodate the item
    let fit_factor = fitting_bins_count as f64 / (open_bins_count as f64 + 1.0);

    // Start with the raw residual
    let mut score = r;

    // Prefer residuals below the current mean – reward with a decreasing factor
    if r < mean_norm {
        let reward = (mean_norm - r) * 0.6 * (1.0 - progress);
        score -= reward;
    } else {
        // Penalise residuals above the mean
        let penalty = (r - mean_norm) * 0.8 * (1.0 - progress);
        score += penalty;
    }

    // Encourage bins that are acceptable for many items
    if fit_factor > 0.5 {
        let bonus = (1.0 - fit_factor) * 0.4 * progress;
        score -= bonus;
    } else {
        let penalty = (1.0 - fit_factor) * 0.2 * progress;
        score += penalty;
    }

    // Look‑ahead: next item fit assessment
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / bin_capacity as f64;
        if r >= next_norm {
            // Good candidate – reward with size of open bins set
            let reward = (1.0 - r) * 0.5 * (1.0 - progress) * (open_bins_count as f64 + 1.0);
            score -= reward;
        } else {
            // Might lead to fragmentation – slight penalty
            let penalty = (next_norm - r) * 0.3 * (1.0 - progress);
            score += penalty;
        }
    }

    // New‑bin penalty – only when a bin is empty
    if bin_residual == bin_capacity {
        let penalty = (open_bins_count as f64 / total_items as f64)
            * 0.3
            * (1.0 - progress);
        score += penalty;
    }

    // Early‑stream small‑residual penalty
    if progress < 0.2 && r < 0.03 {
        score += 0.1;
    }

    // Additional bonus for bins that are almost full but still fit the next item
    if r > 0.8 && next_item_size > 0 {
        let next_norm = next_item_size as f64 / bin_capacity as f64;
        if r >= next_norm {
            score -= 0.05;
        }
    }

    // Encourage smooth residual decreases – penalise large jumps
    let r_post = post_residual as f64 / bin_capacity as f64;
    let r_pre = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    if r_pre > r_post {
        let jump = (r_pre - r_post).max(0.0);
        if jump > 0.2 {
            score += 0.05 * jump;
        }
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // --- Waste penalty (lighter than before) ----------
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    let mut score = waste_ratio * 12.0;

    // --- Deviation from running mean (quadratic) ----
    let delta_mean = (post_residual as f64 - mean_residual).abs();
    score += delta_mean.powi(2) * 0.08;

    // --- Gap penalty if next item won't fit ----------
    if next_item_size > post_residual {
        let gap = (next_item_size - post_residual) as f64;
        score += gap.powi(2) * 0.15;
    }

    // --- Single‑fitting‑bin penalty for low residual --
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual as f64 <= mean_residual * 1.05 {
            score += 6.0;
        }
    }

    // --- New‑bin candidate handling -------------------
    if bin_residual == bin_capacity {
        let ratio = item_size as f64 / bin_capacity as f64;
        score -= ratio * 12.0;
        score -= (open_bins_count as f64).sqrt() * 0.3;
    }

    // --- Late‑stream bias: favor existing bins ----------
    let fraction_done = step_index as f64 / total_items as f64;
    if fraction_done > 0.85 {
        if bin_residual != bin_capacity {
            score += 4.0;
        } else {
            score -= 4.0;
        }
    }

    // --- Penalize excessive open bins ------------------
    let max_allowed = (total_items as f64 * 0.04).max(4.0);
    if open_bins_count as f64 > max_allowed {
        score += 0.2 * (open_bins_count as f64 - max_allowed);
    }

    // --- Reward packing a large fraction of the bin ---
    score -= (item_size as f64 / bin_capacity as f64).powi(2) * 8.0;

    // --- Avoid huge residual when next item tiny -------
    if next_item_size < 3 && post_residual > 12 {
        score += 2.0;
    }

    // --- Encourage bins that match the mean residual --
    if delta_mean < mean_residual * 0.04 {
        score -= 1.5;
    }

    // --- Strong penalty for many bins but huge waste ----
    if fitting_bins_count > 3 {
        let waste = waste_ratio.powi(2);
        score += waste * 2.5;
    }

    // --- Extra penalty for over‑open bins (quadratic tail) ---
    let open_limit = (total_items as f64 * 0.06) as usize;
    if open_bins_count > open_limit {
        let excess = (open_bins_count - open_limit) as f64;
        score += excess.powi(2) * 0.001;
    }

    // --- Lookahead anticipation -------------------------
    if next_item_size > post_residual && bin_residual as f64 > mean_residual * 1.2 {
        score += 3.0;
    }

    // --- Extreme late‑stream hard penalty ----------------
    if fraction_done > 0.95 && bin_residual as f64 > mean_residual * 1.5 {
        score += 5.0;
    }

    score
}

